output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper must take the available entrance cart before doing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items should only be picked up while the shopper is pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper must not carry merchandise by hand rather than in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart_storage": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "becomes_hand_carrying": {
          "pre": "PICKUP_ITEM",
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_used_cart_to_nw_bay",
    "text": "Any cart that is taken must eventually be returned to the northwest cart bay before the shopper leaves.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "nw_cart_bay": "at(0,1)",
        "cart_parked_at_nw_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "pushing_cart"
        },
        "cart_returned_to_nw_bay": {
          "pre": {
            "and": [
              "pushing_cart",
              "nw_cart_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_nw_bay"
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "A cart may only be left at the designated northwest cart bay.",
    "abstraction": {
      "state_properties": {
        "nw_cart_bay": "at(0,1)",
        "away_from_nw_cart_bay": {
          "not": "nw_cart_bay"
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "leave_cart_away_from_bay": {
          "pre": {
            "and": [
              "pushing_cart",
              "LEAVE_CART",
              "away_from_nw_cart_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_bay"
    }
  },
  {
    "id": "exit_only_after_cart_secured",
    "text": "The shopper may exit only after the cart has been parked at the northwest bay and the shopper is no longer pushing it.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_secured": "cartAt(0,1)",
        "ready_to_exit": {
          "and": [
            "cart_secured",
            {
              "not": "pushing_cart"
            }
          ]
        }
      },
      "events": {
        "improper_exit_with_unsecured_cart": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "ready_to_exit"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_exit_with_unsecured_cart"
    }
  },
  {
    "id": "no_carts_in_exit_lobby",
    "text": "Shopping carts are not allowed in the east exit lobby or final exit approach.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "exit_lobby": {
          "or": [
            "at(7,5)",
            "at(8,5)",
            "at(9,5)",
            "at(9,4)",
            "at(8,4)",
            "at(7,4)"
          ]
        },
        "cart_in_exit_lobby": {
          "and": [
            "pushing_cart",
            "exit_lobby"
          ]
        }
      },
      "events": {
        "move_cart_into_exit_lobby": {
          "pre": {
            "and": [
              "pushing_cart",
              "MOVE"
            ]
          },
          "post": "cart_in_exit_lobby"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_lobby"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the bay, the shopper must not perform any further store interaction before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_nw_bay": "cartAt(0,1)",
        "after_cart_return_phase": "cart_parked_at_nw_bay"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "after_cart_return_phase",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
